"""Persistent CPU model process. JSON control only; audio never crosses stdout."""
import json
from pathlib import Path
import struct
import sys
import time

# Also works when invoked directly from an unpacked Skill, with no PYTHONPATH.
sys.path.insert(0, str(Path(__file__).resolve().parents[1]))
from runtime.asr_model import MODEL, VERSION, ModelError, checked_model


def dependencies():
    try:
        import numpy as np
        import sherpa_onnx as sherpa
    except (ImportError, OSError):
        raise ModelError('ASR_DEPENDENCY_UNAVAILABLE') from None
    if sherpa.__version__ != VERSION: raise ModelError('ASR_DEPENDENCY_INCOMPATIBLE')
    return np, sherpa


def wav_pcm(data):
    """Strict RIFF/S16LE validator including duplicate/truncated chunks."""
    def invalid(): raise ModelError('ASR_INVALID_PCM')
    if len(data) < 44 or len(data) > 6_000_000 or data[:4] != b'RIFF' or data[8:12] != b'WAVE': invalid()
    if struct.unpack_from('<I', data, 4)[0] + 8 != len(data): invalid()
    offset, pcm, fmt = 12, None, False
    while offset + 8 <= len(data):
        name, size = struct.unpack_from('<4sI', data, offset)
        offset += 8
        if offset + size > len(data): invalid()
        if name == b'fmt ':
            if fmt or size < 16: invalid()
            tag, channels, rate, byte_rate, align, bits = struct.unpack_from('<HHIIHH', data, offset)
            if (tag, channels, rate, byte_rate, align, bits) != (1, 1, 16000, 32000, 2, 16): invalid()
            fmt = True
        elif name == b'data':
            if pcm is not None: invalid()
            pcm = data[offset:offset+size]
        offset += size + size % 2
    if offset != len(data) or not fmt or not pcm or len(pcm) % 2: invalid()
    return pcm


def subtitle(text, begin, end):
    if not isinstance(text, str) or not text.strip(): raise ModelError('ASR_EMPTY_SPEECH')
    result = dict(text=text.replace('<unk>', '〔未识别〕').strip(), start_ms=round(begin/16), end_ms=round(end/16))
    if '<unk>' in text:
        result['asr_quality'] = dict(raw_text=text, unresolved_unknowns=text.count('<unk>'))
    return result


class StreamingRecognizer:
    """One resident model, incremental decoding; only final utterances are evidence."""
    def __init__(self, recognizer, offset_ms=0):
        self.owner=recognizer
        self.rec=recognizer.recognizer
        self.vad=recognizer.vad
        if hasattr(recognizer,'vad_config'):
            config=recognizer.vad_config
            config.silero_vad.max_speech_duration=100
            self.vad=recognizer.sherpa.VoiceActivityDetector(config,buffer_size_in_seconds=200)
            config.silero_vad.max_speech_duration=20
        self.offset_ms=offset_ms
        self.total=self.begin=0
        self.prefix=""
        self.tail=self.owner.np.zeros(0,dtype=self.owner.np.float32)
        self.reset()

    def reset(self,context=None):
        self.stream=self.rec.create_stream()
        self.vad.reset()
        self.vad_origin=self.total
        self.speech=False
        self.prefix=""
        if context is not None and len(context):
            # A silence-only visual boundary may precede the VAD trigger by a
            # few samples. Preserve 200 ms of real audio without adding time.
            self.vad_origin-=len(context)
            self.vad.accept_waveform(context)
            self.stream.accept_waveform(16000,context)
            while self.rec.is_ready(self.stream):self.rec.decode_stream(self.stream)

    def finish_unit(self, continuation=False):
        if self.total==self.begin:return None
        if not continuation:
            self.stream.accept_waveform(16000,self.owner.np.zeros(4800,dtype=self.owner.np.float32))
            self.stream.input_finished()
        while self.rec.is_ready(self.stream):self.rec.decode_stream(self.stream)
        full_text=self.rec.get_result(self.stream)
        # Keep the decoder/acoustic context across the 20-second boundary.
        # Previously finalized text is context only, never emitted twice.
        shared=0
        for a,b in zip(self.prefix,full_text):
            if a!=b:break
            shared+=1
        text=full_text[shared:]
        a=self.offset_ms+round(self.begin/16)
        b=self.offset_ms+round(self.total/16)
        value={'start_ms':a,'end_ms':b,'text':text.replace('<unk>','〔未识别〕').strip(),
               'speech_detected':self.speech,'continuation':continuation,
               'error':'ASR_EMPTY_SPEECH' if self.speech and not text.strip() else None}
        self.begin=self.total
        if continuation:
            self.prefix=full_text
            self.speech=False
        else:self.reset(self.tail if not self.speech and not text.strip() else None)
        return value

    def feed(self,pcm):
        samples=self.owner.np.frombuffer(pcm,dtype='<i2').astype(self.owner.np.float32)/32768.0
        finals=[]
        for pos in range(0,len(samples),1600):
            block=samples[pos:pos+1600]
            self.total+=len(block)
            self.tail=self.owner.np.concatenate((self.tail,block))[-3200:]
            self.vad.accept_waveform(block)
            self.speech=self.speech or self.vad.is_speech_detected() or not self.vad.empty()
            self.stream.accept_waveform(16000,block)
            while self.rec.is_ready(self.stream):self.rec.decode_stream(self.stream)
            duration=self.total-self.begin
            if not self.vad.empty() or duration>=320000 or (not self.speech and duration>=160000):
                if not self.vad.empty() and hasattr(self.vad,'front'):
                    voice=self.vad.front
                    # A VAD endpoint after a continuation may contain only the
                    # previous unit's speech plus this unit's trailing silence.
                    self.speech=self.vad_origin+voice.start+len(voice.samples)>self.begin
                finals.append(self.finish_unit(continuation=duration>=320000))
        return {'finals':finals,'partial':self.rec.get_result(self.stream),
                'start_ms':self.offset_ms+round(self.begin/16),'end_ms':self.offset_ms+round(self.total/16)}

    def finish(self):
        value=self.finish_unit()
        return {'finals':[value] if value else [],'partial':''}


class Recognizer:
    def __init__(self, root):
        self.np, sherpa = dependencies()
        model = root / 'model' / MODEL
        self.recognizer = sherpa.OnlineRecognizer.from_transducer(
            tokens=str(model/'tokens.txt'), encoder=str(model/'encoder.int8.onnx'),
            decoder=str(model/'decoder.onnx'), joiner=str(model/'joiner.int8.onnx'),
            num_threads=2, sample_rate=16000, feature_dim=80, decoding_method='greedy_search',
            enable_endpoint_detection=False, provider='cpu')
        config = sherpa.VadModelConfig()
        config.sample_rate, config.num_threads, config.provider = 16000, 1, 'cpu'
        config.silero_vad.model = str(root/'vad/silero_vad.onnx')
        config.silero_vad.threshold = .5
        config.silero_vad.min_silence_duration = .5
        config.silero_vad.min_speech_duration = .1
        config.silero_vad.max_speech_duration = 20
        config.silero_vad.window_size = 512
        self.vad_config,self.sherpa=config,sherpa
        self.vad = sherpa.VoiceActivityDetector(config, buffer_size_in_seconds=200)

    def transcribe(self, pcm):
        np, vad, rec = self.np, self.vad, self.recognizer
        started = time.monotonic()
        samples = np.frombuffer(pcm, dtype='<i2').astype(np.float32) / 32768.0
        vad.reset()
        for pos in range(0, len(samples), 512):
            window = samples[pos:pos+512]
            if len(window) < 512: window = np.pad(window, (0, 512-len(window)))
            vad.accept_waveform(window)
        vad.flush()
        ranges = []
        while not vad.empty():
            segment = vad.front
            begin = max(0, segment.start - 2400, ranges[-1][1] if ranges else 0)
            end = min(len(samples), segment.start + len(segment.samples) + 2400)
            if end > begin: ranges.append((begin, end))
            vad.pop()
        output, calls, gaps = [], 0, []
        for low, high in ranges:
            for begin in range(low, high, 320000):
                end = min(begin+320000, high)
                if not np.any(samples[begin:end]): continue
                stream = rec.create_stream()
                for pos in range(begin, end, 5120):
                    stream.accept_waveform(16000, samples[pos:min(pos+5120, end)])
                    while rec.is_ready(stream): rec.decode_stream(stream)
                # Synthetic right context must not extend evidence timestamps.
                stream.accept_waveform(16000, np.zeros(4800, dtype=np.float32))
                stream.input_finished()
                while rec.is_ready(stream): rec.decode_stream(stream)
                try:output.append(subtitle(rec.get_result(stream), begin, end))
                except ModelError as error:
                    if error.code!='ASR_EMPTY_SPEECH':raise
                    gaps.append({'start_ms':round(begin/16),'end_ms':round(end/16),'code':error.code})
                calls += 1
        return dict(subtitles=output, speech_gaps=gaps, duration_ms=len(pcm)/32, processing_ms=round((time.monotonic()-started)*1000),
                    dropped_audio_ms=0, asr_mode='single_pass', asr_calls=calls)


def run():
    recognizer, task_root, streaming, raw_path, raw_offset = None, None, None, None, 0
    # Binary streams avoid Windows newline and locale transformations.
    while True:
        line = sys.stdin.buffer.readline(65537)
        if not line or len(line) > 65536: break
        rid = None
        try:
            request = json.loads(line)
            rid = request['id']
            if not isinstance(rid, str) or len(rid) > 128: raise ModelError('ASR_PROTOCOL_ERROR')
            command = request['command']
            if command in ('check', 'initialize') and recognizer is None:
                dependencies()
                root, value = checked_model(request['runtime_root'])
                if command == 'initialize':
                    task_root = Path(request['task_root']).resolve(strict=True)
                    recognizer = Recognizer(root)
            elif command == 'transcribe' and recognizer:
                path = Path(request['audio_path']).resolve(strict=True)
                if not path.is_relative_to(task_root) or not path.is_file(): raise ModelError('ASR_INVALID_PCM')
                with path.open('rb') as audio: pcm = wav_pcm(audio.read(6_000_001))
                value = recognizer.transcribe(pcm)
            elif command == 'stream-start' and recognizer:
                path=Path(request['audio_path']).resolve(strict=True)
                if not path.is_relative_to(task_root) or not path.is_file():raise ModelError('ASR_INVALID_PCM')
                offset=request.get('byte_offset',0)
                if type(offset) is not int or offset<0 or offset%2 or offset>path.stat().st_size:raise ModelError('ASR_INVALID_PCM')
                timestamp=request.get('offset_ms',0)
                if type(timestamp) is not int or timestamp<0:raise ModelError('ASR_INVALID_PCM')
                raw_path,raw_offset=path,offset
                streaming=StreamingRecognizer(recognizer,request.get('offset_ms',0))
                value={'started':True}
            elif command == 'stream-read' and streaming:
                count=request.get('bytes',3200)
                if type(count) is not int or not 0<count<=32000 or count%2:raise ModelError('ASR_INVALID_PCM')
                with raw_path.open('rb') as audio:
                    audio.seek(raw_offset);pcm=audio.read(count)
                pcm=pcm[:len(pcm)//2*2]
                raw_offset+=len(pcm)
                value={**streaming.feed(pcm),'bytes_read':len(pcm)}
            elif command == 'stream-finish' and streaming:
                value=streaming.finish();streaming=None
            else: raise ModelError('ASR_PROTOCOL_ERROR')
            response = dict(id=rid, ok=True, value=value)
        except Exception as error:
            code = error.code if isinstance(error, ModelError) else 'ASR_PROTOCOL_ERROR'
            response = dict(id=rid, ok=False, error=dict(code=code))
        sys.stdout.buffer.write((json.dumps(response, ensure_ascii=True, allow_nan=False)+'\n').encode('ascii'))
        sys.stdout.buffer.flush()


if __name__ == '__main__': run()

d670eb309e6d4395587300175ee3f4e5042abc34.text:
"""Shared output protocol + helpers for the verifier CLI.

Every ``cmd_*`` function in lib/<family>.py SHOULD return a plain dict and
let the dispatcher in bin/verifier wrap it via ``ok()`` / ``err()`` and
``emit()`` it.  Functions MAY raise ``VerifierError`` to bubble a
recoverable error up; anything else propagates as an unhandled exception.

Output schema (one JSON object on stdout, no extra text):

    {"ok": true,  "tool": "<family>.<sub>", "result": {...}, "evidence": {...}}
    {"ok": false, "tool": "<family>.<sub>", "error": {"code": "...", "msg": "..."}}

``evidence`` is intentionally separate from ``result``: ``result`` is the
machine-readable answer; ``evidence`` is the human-quotable string the
judge can paste into ``questionnaire.md`` rationale.
"""
from __future__ import annotations

import argparse
import json
import mimetypes
import os
import pathlib
import shutil
import sys
from typing import Any


# ---------------------------------------------------------------------------
# Error codes — kept as a flat enum so SKILL.md / agent prompts can list them.
# ---------------------------------------------------------------------------

class ErrCode:
    FILE_NOT_FOUND = "FILE_NOT_FOUND"
    NOT_A_FILE = "NOT_A_FILE"
    BAD_EXT = "BAD_EXT"
    PARSE_ERROR = "PARSE_ERROR"
    LOCATOR_INVALID = "LOCATOR_INVALID"
    NOT_FOUND = "NOT_FOUND"
    DEP_MISSING = "DEP_MISSING"
    BAD_ARGS = "BAD_ARGS"
    INTERNAL = "INTERNAL"


class VerifierError(Exception):
    """Recoverable, JSON-serializable error from a verifier subcommand."""
    def __init__(self, code: str, msg: str) -> None:
        super().__init__(msg)
        self.code = code
        self.msg = msg


# ---------------------------------------------------------------------------
# Output wrappers
# ---------------------------------------------------------------------------

def ok(tool: str, result: Any, evidence: Any | None = None) -> dict:
    out: dict = {"ok": True, "tool": tool, "result": result}
    if evidence is not None:
        out["evidence"] = evidence
    return out


def err(tool: str, code: str, msg: str) -> dict:
    return {"ok": False, "tool": tool, "error": {"code": code, "msg": msg}}


def emit(payload: dict) -> int:
    """Write a single-line JSON to stdout; return shell exit code."""
    print(json.dumps(payload, ensure_ascii=False))
    return 0 if payload.get("ok") else 1


# ---------------------------------------------------------------------------
# argparse integration
#
# argparse's default ``error()`` prints usage to stderr and exits 2, which
# would break the "every invocation prints one JSON object on stdout" contract.
# ``JsonArgumentParser`` turns those into VerifierError(BAD_ARGS) so the
# dispatcher can emit a normal error envelope.  ``--help`` still behaves
# normally because help goes through ``exit()``, not ``error()``.
# ---------------------------------------------------------------------------

class JsonArgumentParser(argparse.ArgumentParser):
    def error(self, message: str) -> Any:  # type: ignore[override]
        raise VerifierError(ErrCode.BAD_ARGS, f"{self.prog}: {message}")


# ---------------------------------------------------------------------------
# Dependency install hint
#
# The rollout sandbox refuses a plain ``pip install``: the user site lacks
# sys.path precedence and the venv's site-packages is not writable.  Installing
# into a private directory and putting it on PYTHONPATH is the form that works.
# ---------------------------------------------------------------------------

PYLIBS_DIR = "$HOME/.verifier-pylibs"


def install_hint(*dists: str) -> str:
    names = " ".join(dists)
    if os.name == "nt":
        # PowerShell has neither $HOME nor export, so the POSIX hint is not
        # something a Windows user can paste. A user-site install is the
        # simplest form that works there; the --target variant is kept for
        # parity with the sandbox, rewritten in PowerShell syntax.
        return (
            f'install hint (PowerShell): python -m pip install --user {names}  '
            f'or, sandbox-style: pip install --target "$env:USERPROFILE\\.verifier-pylibs" {names}; '
            f'$env:PYTHONPATH = "$env:USERPROFILE\\.verifier-pylibs;$env:PYTHONPATH"'
        )
    return (
        f'install hint: pip install --target "{PYLIBS_DIR}" {names} '
        f'&& export PYTHONPATH="{PYLIBS_DIR}:$PYTHONPATH"  '
        f"(a plain `pip install` fails in the sandbox: the venv site-packages "
        f"is not writable and the user site lacks sys.path precedence)"
    )


# ---------------------------------------------------------------------------
# file:// URIs
#
# ``"file://" + path`` is only correct when ``path`` starts with a slash. On
# Windows it yields ``file://C:\dir\f`` where the drive letter is parsed as the
# URL host, and it also leaves spaces and non-ASCII characters unescaped on
# POSIX. Always go through pathlib's as_uri().
# ---------------------------------------------------------------------------

def path_to_file_uri(path: str) -> str:
    """Absolute filesystem path -> a correctly escaped ``file://`` URI."""
    return pathlib.Path(os.path.abspath(path)).as_uri()


def dir_to_file_uri(path: str) -> str:
    """Same as :func:`path_to_file_uri`, for a directory that need not exist."""
    return pathlib.Path(os.path.abspath(path)).as_uri()


# ---------------------------------------------------------------------------
# Cross-platform external binary discovery
#
# shutil.which() only searches PATH. The LibreOffice installers on Windows and
# macOS do not put their binary on PATH, so PATH lookup alone reports the tool
# as missing on machines where it is installed.
#
# On Windows soffice.com is preferred over soffice.exe: the .exe is a launcher
# that returns immediately, so subprocess.run() would finish before the
# conversion is written to disk.
# ---------------------------------------------------------------------------

_IS_WINDOWS = os.name == "nt"

if _IS_WINDOWS:
    OFFICE_BINARY_NAMES: tuple[str, ...] = ("soffice.com", "soffice", "libreoffice")
else:
    OFFICE_BINARY_NAMES = ("soffice", "libreoffice")


def _office_fallback_paths() -> tuple[str, ...]:
    if _IS_WINDOWS:
        bases = [os.environ.get("ProgramFiles", r"C:\Program Files"),
                 os.environ.get("ProgramFiles(x86)", r"C:\Program Files (x86)")]
        return tuple(
            os.path.join(b, "LibreOffice", "program", exe)
            for b in bases if b for exe in ("soffice.com", "soffice.exe")
        )
    if sys.platform == "darwin":
        return (
            "/Applications/LibreOffice.app/Contents/MacOS/soffice",
            "/opt/homebrew/bin/soffice",
            "/usr/local/bin/soffice",
        )
    return ("/usr/bin/soffice", "/usr/bin/libreoffice",
            "/usr/lib/libreoffice/program/soffice",
            "/snap/bin/libreoffice")


def find_binary(names: tuple[str, ...], fallbacks: tuple[str, ...] = ()) -> str | None:
    """First existing executable among PATH lookups then explicit fallbacks."""
    for name in names:
        p = shutil.which(name)
        if p:
            return p
    for p in fallbacks:
        if p and os.path.isfile(p):
            return p
    return None


def find_office_binary() -> str | None:
    """Locate LibreOffice/soffice on any platform. None when unavailable."""
    return find_binary(OFFICE_BINARY_NAMES, _office_fallback_paths())


# The install command differs per platform, and a hint the reader cannot run is
# worse than no hint: on Windows `apt install libreoffice` just sends the model
# down a dead end. Give the command for the platform we are actually on.

def _office_install_cmd() -> str:
    if _IS_WINDOWS:
        return "`winget install --id TheDocumentFoundation.LibreOffice -e`"
    if sys.platform == "darwin":
        return "`brew install --cask libreoffice`"
    return "`apt install libreoffice`"


def office_missing_msg() -> str:
    """The DEP_MISSING message for a missing LibreOffice, platform-correct."""
    return ("LibreOffice not found. Looked for " + ", ".join(OFFICE_BINARY_NAMES)
            + " on PATH plus the standard install locations for this platform. "
              "Install it: " + _office_install_cmd()
            + ". If it is already installed but off PATH (the usual case on "
              "Windows and macOS), pass --soffice <path>.")


# ---------------------------------------------------------------------------
# Path / file helpers
# ---------------------------------------------------------------------------

def resolve_path(p: str) -> str:
    """Expand ``~`` and resolve to absolute path, but do NOT require existence."""
    return os.path.abspath(os.path.expanduser(p))


def require_file(path: str, expected_exts: tuple[str, ...] | None = None) -> str:
    """Validate that ``path`` is an existing file and (optionally) has an allowed extension.

    Raises VerifierError on any failure.  Returns the absolute path.
    """
    abs_path = resolve_path(path)
    if not os.path.exists(abs_path):
        raise VerifierError(ErrCode.FILE_NOT_FOUND, f"file does not exist: {abs_path}")
    if not os.path.isfile(abs_path):
        raise VerifierError(ErrCode.NOT_A_FILE, f"not a regular file: {abs_path}")
    if expected_exts:
        ext = os.path.splitext(abs_path)[1].lower()
        if ext not in expected_exts:
            raise VerifierError(
                ErrCode.BAD_EXT,
                f"unsupported extension {ext!r} for {abs_path}; expected one of {list(expected_exts)}",
            )
    return abs_path


def detect_kind(path: str) -> str:
    """Cheap file-kind detector based on extension + mimetype.

    Returns one of: ``xlsx``, ``docx``, ``pdf``, ``pptx``, ``text``, ``image``,
    ``binary``, ``unknown``.  Used by ``file_io.artifact_list``.
    """
    ext = os.path.splitext(path)[1].lower()
    if ext in (".xlsx", ".xlsm"):
        return "xlsx"
    if ext in (".docx", ".docm"):
        return "docx"
    if ext == ".pdf":
        return "pdf"
    if ext in (".pptx", ".pptm"):
        return "pptx"
    if ext in (".md", ".txt", ".csv", ".html", ".htm", ".json", ".yaml", ".yml", ".log"):
        return "text"
    if ext in (".png", ".jpg", ".jpeg", ".gif", ".webp", ".svg"):
        return "image"
    mime, _ = mimetypes.guess_type(path)
    if mime and mime.startswith("text/"):
        return "text"
    if mime and mime.startswith("image/"):
        return "image"
    if mime is None:
        return "unknown"
    return "binary"


def file_size(path: str) -> int:
    try:
        return os.path.getsize(path)
    except OSError:
        return -1


# ---------------------------------------------------------------------------
# Lazy-import helper — used by lib/<family>.py whose dependency is heavy /
# may not always be installed.
# ---------------------------------------------------------------------------

# module name -> pip distribution name, where they differ
_DIST_FOR_MODULE = {
    "docx": "python-docx",
    "pptx": "python-pptx",
    "fitz": "pymupdf",
    "yaml": "PyYAML",
    "PIL": "Pillow",
}


def lazy_import(module_name: str, hint: str | None = None) -> Any:
    """Import a module on demand; raise VerifierError(DEP_MISSING) if unavailable."""
    try:
        return __import__(module_name, fromlist=["*"])
    except ImportError as e:
        dist = _DIST_FOR_MODULE.get(module_name, module_name)
        msg = f"required dependency missing: {module_name} ({e}) — "
        msg += hint or install_hint(dist)
        raise VerifierError(ErrCode.DEP_MISSING, msg) from e


# ---------------------------------------------------------------------------
# Locator parsing — the same JSON-blob locator works across families:
#   xlsx: {"sheet": "P&L", "cell": "F12"}
#   docx: {"heading_regex": "区位优势", "min_chars": 80}
# Subcommands accept either ``--locator '<json>'`` or family-specific shorthand
# flags.  Helper kept thin to avoid a per-family JSON-blob bikeshed.
# ---------------------------------------------------------------------------

def parse_locator(raw: str | None) -> dict:
    """Parse a ``--locator`` JSON string; return ``{}`` on None.  Raises BAD_ARGS."""
    if raw is None or raw == "":
        return {}
    try:
        loc = json.loads(raw)
    except json.JSONDecodeError as e:
        raise VerifierError(ErrCode.LOCATOR_INVALID, f"--locator must be JSON: {e}") from e
    if not isinstance(loc, dict):
        raise VerifierError(ErrCode.LOCATOR_INVALID, "--locator JSON must be an object")
    return loc


# ---------------------------------------------------------------------------
# Numeric tolerance — shared between xlsx.assert_value, num.assert and rubric.numeric.
# ---------------------------------------------------------------------------

def in_tolerance(actual: Any, expected: float, tol_abs: float | None,
                 tol_rel: float | None) -> tuple[bool, str]:
    """Return (passed, explanation).  At least one of tol_abs/tol_rel must be given."""
    try:
        a = float(actual)
    except (TypeError, ValueError):
        return False, f"actual value {actual!r} is not numeric"
    e = float(expected)
    if tol_abs is None and tol_rel is None:
        # Default: exact equality
        return a == e, f"expected {e}, actual {a} (exact)"
    if tol_abs is not None and abs(a - e) <= tol_abs:
        return True, f"expected {e}, actual {a}, |Δ|={abs(a - e):.6g} ≤ tol_abs={tol_abs}"
    if tol_rel is not None and e != 0 and abs(a - e) / abs(e) <= tol_rel:
        return True, f"expected {e}, actual {a}, |Δ|/|exp|={abs(a - e) / abs(e):.6g} ≤ tol_rel={tol_rel}"
    parts = [f"expected {e}, actual {a}, |Δ|={abs(a - e):.6g}"]
    if tol_abs is not None:
        parts.append(f"tol_abs={tol_abs}")
    if tol_rel is not None:
        parts.append(f"tol_rel={tol_rel}")
    return False, "; ".join(parts)


# ---------------------------------------------------------------------------
# Evidence helper — keep produced evidence shapes consistent.
# ---------------------------------------------------------------------------

def evidence(file: str | None = None, locator: Any | None = None,
             quote: str | None = None, **extras: Any) -> dict:
    """Build a uniform evidence dict.  ``quote`` is a short human-readable string."""
    out: dict = {}
    if file:
        out["file"] = file
    if locator is not None:
        out["locator"] = locator
    if quote is not None:
        out["quote"] = quote
    for k, v in extras.items():
        out[k] = v
    return out

