        var contentW = pdfW - margin * 2;
        var contentH = pdfH - margin * 2;

        // 计算图片尺寸以适应横向 A4
        var imgW = contentW;
        var imgH = (canvas.height * imgW) / canvas.width;

        // 如果高度仍然超过页面高度，按高度缩放
        if (imgH > contentH) {{
            imgH = contentH;
            imgW = (canvas.width * imgH) / canvas.height;
