}

% ============================================================================
% SCIENTIFIC NOTATION COMMANDS
% ============================================================================

% Highlight important text
\newcommand{\highlight}[1]{\textbf{\textcolor{primaryblue}{#1}}}

% P-value formatting (with significance indicators)
\newcommand{\pvalue}[1]{%
    \textit{p}~=~#1%
}

% Significant p-value (bold)
\newcommand{\psig}[1]{%
    \textbf{\textit{p}~=~#1}%
}

% Confidence interval
\newcommand{\CI}[2]{%
    95\% CI [#1, #2]%
}

% Effect size formatting
